//! End-to-end differential test against the C++ fuzzer driver
//! `tools/oracle/e2e_fuzz.cpp` (golden: `tests/golden/e2e_fuzz.txt`,
//! regenerated by `tools/oracle/e2e_fuzz.sh --golden`).
//!
//! Every golden scene is a random mix of all public libavoid features run
//! through a long sequence of transactions; after every transaction the
//! C++ dumped routes, display routes, junction positions, shapes and pins,
//! hyperedge new/deleted object lists, the callback sequence, the
//! `exists*` queries, `attachedConns`/`attachedShapes` and
//! `outputDiagramText` (or one FNV-1a hash per transaction for large
//! scenes).  The Rust interpreter (`tests/e2e_fuzz_dsl/mod.rs`) must
//! reproduce that output byte for byte.
//!
//! Scene markers (first output line):
//!  * `#assert <msg>`: the asserting C++ build fails an upstream
//!    `COLA_ASSERT`; the expected output is the NDEBUG build's, checked
//!    in debug builds too (the port does not keep asserts that upstream
//!    violates on valid input; see "Asserts" in `src/avoid/router.rs`).
//!  * `#exclude <reason>`: upstream crashes / has undefined behaviour /
//!    times out on this scene (see `tools/oracle/e2e_fuzz.sh`); skipped.
//!    `E2E_SOFT=1` also replays these and reports (without failing) how
//!    many still match the NDEBUG output, which follows the marker.
//!
//! Environment:
//!  * `E2E_GOLDEN=path`  another golden file (fuzz campaigns)
//!  * `E2E_SCENE=name`   only that scene; `E2E_FULL=1` prints its full dump
//!  * `E2E_SUBSAMPLE=k`  only every k-th scene (default 10 in debug builds)
//!  * `E2E_THREADS=n`    worker threads (default: available parallelism)
//!  * `E2E_REPORT=path`  write "name<TAB>status" per scene
//!  * `E2E_RAW=1`        robustness replay: every scene with all interpreter
//!    guards against upstream API misuse off (raw immediate mode, missing
//!    pin classes, cyclic / two-terminal hyperedges, deleting objects with
//!    queued actions, ...); must not panic (no comparison)
//!  * `E2E_ONLY=path`    only the scenes named in that file (one per line)
//!  * `E2E_PROGRESS=1`   print "start NAME" / "done NAME ms STATUS" to stderr
//!    (STATUS as in the report; the campaign driver's watchdog reads these)
//!  * `E2E_NO_SLOT_REUSE=1` arenas never reuse freed slots (results must
//!    not change: a difference means a slot index leaks into behaviour)

#![allow(clippy::uninlined_format_args)]

#[path = "e2e_fuzz_dsl/mod.rs"]
mod e2e_fuzz_dsl;

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

use e2e_fuzz_dsl::{parse_golden, run_scene, run_scene_raw, GoldenScene};

enum Outcome {
    Match,
    Differ(String),
    Panic(String),
    /// `soft_match`: with `E2E_SOFT`, whether the replay matched the NDEBUG
    /// output (None: not replayed / no output); `panic`: the replay panicked.
    Excluded { soft_match: Option<bool>, panic: Option<String> },
}

fn panic_msg(e: Box<dyn std::any::Any + Send>) -> String {
    e.downcast_ref::<String>()
        .cloned()
        .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
        .unwrap_or_default()
}

/// Robustness replay (`E2E_RAW=1`): the scene with all interpreter guards
/// against upstream API misuse off; must not panic.
fn check_raw(scene: &GoldenScene) -> Outcome {
    let dsl = scene.dsl.clone();
    match std::panic::catch_unwind(move || run_scene_raw(&dsl)) {
        Ok(_) => Outcome::Match,
        Err(e) => Outcome::Panic(panic_msg(e)),
    }
}

fn check(scene: &GoldenScene, full: bool, soft: bool) -> Outcome {
    let first = scene.out.first().map(|s| s.as_str()).unwrap_or("");
    let mut expected: &[String] = &scene.out;
    let mut excluded = false;
    if first.starts_with("#exclude") {
        if !soft {
            return Outcome::Excluded { soft_match: None, panic: None };
        }
        excluded = true;
        expected = &scene.out[1..];
        if first.starts_with("#exclude crash") || first == "#exclude memory" {
            // No C++ output: crash/hang-freedom check only.
            let dsl = scene.dsl.clone();
            let panic = std::panic::catch_unwind(move || run_scene(&dsl, false)).err().map(panic_msg);
            return Outcome::Excluded { soft_match: None, panic };
        }
    } else if first.starts_with("#assert") {
        // (The port drops the upstream asserts that upstream itself
        // violates on valid input, so debug builds run these too.)
        expected = &scene.out[1..];
    }
    let dsl = scene.dsl.clone();
    let result = std::panic::catch_unwind(move || run_scene(&dsl, full));
    let outcome = match result {
        Err(e) => Outcome::Panic(panic_msg(e)),
        Ok(out) => {
            if full {
                let mut s = format!("#scene {}\n", scene.name);
                for l in out.iter() {
                    s.push_str(l);
                    s.push('\n');
                }
                print!("{}", s);
            }
            if out == expected {
                Outcome::Match
            } else {
                let k = out
                    .iter()
                    .zip(expected.iter())
                    .position(|(a, b)| a != b)
                    .unwrap_or(out.len().min(expected.len()));
                Outcome::Differ(format!(
                    "first difference at output line {}:\n  rust:   {}\n  oracle: {}",
                    k,
                    out.get(k).map(|s| s.as_str()).unwrap_or("<none>"),
                    expected.get(k).map(|s| s.as_str()).unwrap_or("<none>")
                ))
            }
        }
    };
    if excluded {
        let panic = if let Outcome::Panic(m) = &outcome { Some(m.clone()) } else { None };
        return Outcome::Excluded { soft_match: Some(matches!(outcome, Outcome::Match)), panic };
    }
    outcome
}

/// One-line status of a scene (report file and progress lines).  An
/// excluded scene that panicked is "excluded-panic MSG".
fn status_of(o: &Outcome) -> String {
    let first_line = |m: &str| m.lines().next().unwrap_or("").to_string();
    match o {
        Outcome::Match => "match".to_string(),
        Outcome::Excluded { panic: Some(m), .. } => format!("excluded-panic {}", first_line(m)),
        Outcome::Excluded { soft_match: Some(true), .. } => "excluded-match".to_string(),
        Outcome::Excluded { soft_match: Some(false), .. } => "excluded-differ".to_string(),
        Outcome::Excluded { soft_match: None, .. } => "excluded".to_string(),
        Outcome::Differ(_) => "differ".to_string(),
        Outcome::Panic(m) => format!("panic {}", first_line(m)),
    }
}

#[test]
fn e2e_fuzz_matches_cpp_oracle() {
    let custom = std::env::var("E2E_GOLDEN").ok();
    let path = custom
        .clone()
        .unwrap_or_else(|| concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/e2e_fuzz.txt").to_string());
    let text = std::fs::read_to_string(&path).expect("golden file");
    let scenes = parse_golden(&text);
    assert!(custom.is_some() || scenes.len() >= 1000, "golden file looks truncated");
    if std::env::var("E2E_NO_SLOT_REUSE").is_ok() {
        libavoid_rust::avoid::arena::NO_SLOT_REUSE.store(true, std::sync::atomic::Ordering::Relaxed);
    }
    let only = std::env::var("E2E_SCENE").ok();
    let only_set: Option<std::collections::HashSet<String>> = std::env::var("E2E_ONLY")
        .ok()
        .map(|p| std::fs::read_to_string(p).expect("E2E_ONLY file").lines().map(|l| l.to_string()).collect());
    let full = std::env::var("E2E_FULL").is_ok();
    let soft = std::env::var("E2E_SOFT").is_ok();
    let raw = std::env::var("E2E_RAW").is_ok();
    let progress = std::env::var("E2E_PROGRESS").is_ok();
    let max_ms = std::sync::atomic::AtomicU64::new(0);
    let subsample: usize = std::env::var("E2E_SUBSAMPLE")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(if cfg!(debug_assertions) && custom.is_none() { 10 } else { 1 });
    let selected: Vec<&GoldenScene> = scenes
        .iter()
        .enumerate()
        .filter(|(i, s)| match (only.as_ref(), only_set.as_ref()) {
            (Some(o), _) => &s.name == o,
            (None, Some(set)) => set.contains(&s.name),
            (None, None) => i % subsample == 0,
        })
        .map(|(_, s)| s)
        .collect();
    let threads: usize = std::env::var("E2E_THREADS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or_else(|| std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4));
    // Silence the default panic message spam of caught panics.
    // (kept for single-scene runs, where the backtrace is useful)
    let prev_hook = std::panic::take_hook();
    if only.is_none() || only_set.is_some() {
        std::panic::set_hook(Box::new(|_| {}));
    }
    let next = AtomicUsize::new(0);
    let results: Mutex<Vec<(usize, Outcome)>> = Mutex::new(Vec::new());
    std::thread::scope(|s| {
        for _ in 0..threads.max(1) {
            s.spawn(|| loop {
                let i = next.fetch_add(1, Ordering::SeqCst);
                if i >= selected.len() {
                    break;
                }
                let t0 = std::time::Instant::now();
                if progress {
                    eprintln!("start {}", selected[i].name);
                }
                let o = if raw { check_raw(selected[i]) } else { check(selected[i], full, soft) };
                let ms = t0.elapsed().as_millis() as u64;
                max_ms.fetch_max(ms, Ordering::SeqCst);
                if progress {
                    eprintln!("done {} {} ms {}", selected[i].name, ms, status_of(&o));
                }
                results.lock().unwrap().push((i, o));
            });
        }
    });
    std::panic::set_hook(prev_hook);
    let mut results = results.into_inner().unwrap();
    results.sort_by_key(|(i, _)| *i);
    let (mut matched, mut excluded, mut soft_ok, mut soft_bad) = (0, 0, 0, 0);
    let mut failures = Vec::new();
    let mut report = String::new();
    for (i, o) in results.iter() {
        let name = &selected[*i].name;
        let status = status_of(o);
        match o {
            Outcome::Match => matched += 1,
            Outcome::Excluded { soft_match, panic } => {
                excluded += 1;
                if let Some(m) = panic {
                    // The port must not panic even where upstream is
                    // undefined.
                    failures.push(format!("{}: (excluded scene) panicked: {}", name, m));
                }
                match soft_match {
                    Some(true) => soft_ok += 1,
                    Some(false) => soft_bad += 1,
                    None => {}
                }
            }
            Outcome::Differ(m) => failures.push(format!("{}: {}", name, m)),
            Outcome::Panic(m) => failures.push(format!("{}: panicked: {}", name, m)),
        }
        report.push_str(&format!("{}\t{}\n", name, status));
    }
    if let Ok(p) = std::env::var("E2E_REPORT") {
        std::fs::write(p, report).expect("write report");
    }
    println!(
        "{}{} scenes in golden, {} selected: {} match, {} differ/panic, {} excluded (soft replay: {} match, {} differ); slowest scene {} ms",
        if raw { "[raw robustness replay] " } else { "" },
        scenes.len(),
        selected.len(),
        matched,
        failures.len(),
        excluded,
        soft_ok,
        soft_bad,
        max_ms.load(Ordering::SeqCst)
    );
    assert!(failures.is_empty(), "{} scene(s) differ:\n{}", failures.len(), failures.join("\n"));
}

/// Minimised scenes of the divergences the fuzzer found (one per fixed
/// port bug; `tests/golden/e2e_fuzz_regressions.txt`, C++ NDEBUG output),
/// plus `reg-unifying-all-pairs`, a defined scene whose unifying nudging
/// stage tries all F(F-1)/2 pairs of free segments (PORTING.md, "Known
/// slow cases"; C++ output identical under both allocators).
#[test]
fn e2e_fuzz_regressions() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/e2e_fuzz_regressions.txt");
    let scenes = parse_golden(&std::fs::read_to_string(path).expect("regression golden"));
    let mut failures = Vec::new();
    for scene in scenes.iter() {
        // (soft: "#exclude crash" scenes -- upstream crashes or never
        // returns -- must run to completion without panicking, in debug
        // builds too)
        match check(scene, false, true) {
            Outcome::Match | Outcome::Excluded { soft_match: None | Some(true), panic: None } => {}
            Outcome::Differ(m) => failures.push(format!("{}: {}", scene.name, m)),
            Outcome::Panic(m) => failures.push(format!("{}: panicked: {}", scene.name, m)),
            Outcome::Excluded { panic: Some(m), .. } => failures.push(format!("{}: panicked: {}", scene.name, m)),
            Outcome::Excluded { .. } => failures.push(format!("{}: differs", scene.name)),
        }
        // A scene marked "[linear N]" ends with N transactions that queue
        // nothing; on such transactions upstream's hyperedge improvement
        // may add the same number of junctions and connectors every time
        // (router.rs, "Known upstream behaviour"), so the total number of
        // display-route points, connectors and junctions must grow by the
        // same amount on each of them: no growth that compounds.
        if let Some(n) = linear_marker(scene) {
            if let Err(m) = check_linear_growth(&scene.dsl, n) {
                failures.push(format!("{}: {}", scene.name, m));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

fn linear_marker(scene: &GoldenScene) -> Option<usize> {
    let first = scene.out.first()?;
    let start = first.find("[linear ")? + "[linear ".len();
    let len = first[start..].find(']')?;
    first[start..start + len].parse().ok()
}

/// Per-transaction (route points, connectors, junctions) of a full dump.
fn transaction_totals(out: &[String]) -> Vec<[usize; 3]> {
    let mut res: Vec<[usize; 3]> = Vec::new();
    for line in out {
        if line.starts_with("T ") {
            res.push([0; 3]);
        } else if let Some(t) = res.last_mut() {
            if let Some(rest) = line.strip_prefix("  disp ") {
                t[0] += rest.split(':').next().and_then(|n| n.parse::<usize>().ok()).unwrap_or(0);
            } else if line.starts_with("C ") {
                t[1] += 1;
            } else if line.starts_with("J ") {
                t[2] += 1;
            }
        }
    }
    res
}

fn check_linear_growth(dsl: &[String], n: usize) -> Result<(), String> {
    let out = run_scene(dsl, true);
    let totals = transaction_totals(&out);
    if totals.len() < n + 1 {
        return Err(format!("only {} transactions", totals.len()));
    }
    let tail = &totals[totals.len() - n - 1..];
    let step = |k: usize| -> [i64; 3] {
        let (a, b) = (tail[k], tail[k + 1]);
        [0, 1, 2].map(|i| b[i] as i64 - a[i] as i64)
    };
    let first = step(0);
    for k in 1..n {
        if step(k) != first {
            return Err(format!(
                "growth per empty transaction not constant: {:?} then {:?} (points, connectors, junctions; totals {:?})",
                first,
                step(k),
                tail
            ));
        }
    }
    Ok(())
}
